const data = parseCSV(CSV);
const years = [...new Set(data.map(r => Number(r.year)))].sort((a, b) => a - b);
const sources = [...new Set(data.map(r => r.source).filter(Boolean))];
const YEAR = 2023;

const fmt = n => n.toLocaleString("en-US");
const pct = (part, whole) => (whole ? (part / whole) * 100 : 0);

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
  }[c]));
}

function render(year) {
  const rows = data
    .filter(r => Number(r.year) === year)
    .map(r => ({
      district: r.district,
      due: Number(r.children_due),
      immu: Number(r.children_fully_immunised),
      rate: pct(Number(r.children_fully_immunised), Number(r.children_due)),
    }));

  // Rank: best coverage first
  rows.sort((a, b) => b.rate - a.rate);
  const lowest = rows[rows.length - 1];

  // Lowest-district callout
  document.getElementById("lowestPanel").innerHTML =
    '<h2>Lowest coverage in ' + year + '</h2>' +
    '<p class="sub">The district with the lowest immunisation coverage for this year.</p>' +
    '<div class="callout">' +
    '<div class="callout-dist">' + escapeHtml(lowest.district) + '<small>lowest coverage</small></div>' +
    '<div class="callout-metric">' + lowest.rate.toFixed(1) + '%<small>' + fmt(lowest.immu) + ' of ' + fmt(lowest.due) + ' children fully immunised</small></div>' +
    '</div>';

  // Bars
  const barsEl = document.getElementById("bars");
  barsEl.innerHTML = "";
  rows.forEach((r, i) => {
    const row = document.createElement("div");
    const isTop = i === 0;
    const isLow = i === rows.length - 1;
    row.className = "bar-row" + (isTop ? " rank-1" : "") + (isLow ? " rank-low" : "");
    row.innerHTML =
      '<div class="bar-label">' + escapeHtml(r.district) +
      '<small>due ' + fmt(r.due) + '</small></div>' +
      '<div class="bar-track"><div class="bar-fill' + (isTop ? ' top' : '') + (isLow ? ' low' : '') + '"></div></div>' +
      '<div class="bar-pct">' + r.rate.toFixed(1) + '%</div>';
    barsEl.appendChild(row);
    const fill = row.querySelector(".bar-fill");
    requestAnimationFrame(() => { fill.style.width = Math.min(100, r.rate) + "%"; });
  });

  // Table
  const tbody = document.getElementById("tableBody");
  tbody.innerHTML = "";
  rows.forEach((r, i) => {
    const isTop = i === 0;
    const isLow = i === rows.length - 1;
    let tag = "";
    if (isTop) tag = '<span class="tag">top</span>';
    else if (isLow) tag = '<span class="tag low">lowest</span>';
    const tr = document.createElement("tr");
    tr.className = isLow ? "low-row" : "";
    tr.innerHTML =
      '<td>' + escapeHtml(r.district) + tag + '</td>' +
      '<td>' + fmt(r.due) + '</td>' +
      '<td>' + fmt(r.immu) + '</td>' +
      '<td>' + r.rate.toFixed(1) + '%</td>';
    tbody.appendChild(tr);
  });

  // Totals
  const tDue = rows.reduce((s, r) => s + r.due, 0);
  const tImmu = rows.reduce((s, r) => s + r.immu, 0);
  document.getElementById("tDue").textContent = fmt(tDue);
  document.getElementById("tImmu").textContent = fmt(tImmu);
  document.getElementById("tPct").textContent = pct(tImmu, tDue).toFixed(1) + "%";

  // Summary line
  const best = rows[0];
  document.getElementById("summary").innerHTML =
    '<b>' + rows.length + '</b> districts · highest: <b>' + escapeHtml(best.district) +
    '</b> (' + best.rate.toFixed(1) + '%) · lowest: <b>' + escapeHtml(lowest.district) +
    '</b> (' + lowest.rate.toFixed(1) + '%)';
}

