// ---- Download 2023 table as CSV ----
function buildCSV(year) {
  const rows = data
    .filter(r => Number(r.year) === year)
    .map(r => ({
      district: r.district,
      due: Number(r.children_due),
      immu: Number(r.children_fully_immunised),
      rate: pct(Number(r.children_fully_immunised), Number(r.children_due)),
      source: r.source,
    }));
  rows.sort((a, b) => b.rate - a.rate);

  const escape = v => {
    const s = String(v);
    return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  };
  const lines = ["district,children_due,children_fully_immunised,coverage_percent,source"];
  rows.forEach(r => {
    lines.push([escape(r.district), r.due, r.immu, r.rate.toFixed(1), escape(r.source)].join(","));
  });
  const tDue = rows.reduce((s, r) => s + r.due, 0);
  const tImmu = rows.reduce((s, r) => s + r.immu, 0);
  lines.push(["Total", tDue, tImmu, pct(tImmu, tDue).toFixed(1), ""].join(","));
  return lines.join("\n") + "\n";
}

function downloadCSV(year) {
  const csv = buildCSV(year);
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = "district_immunisation_" + year + ".csv";
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

document.getElementById("downloadBtn").addEventListener("click", () => downloadCSV(YEAR));

render(YEAR);

